import{_ as o,o as d,c,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"主键策略","description":"","frontmatter":{"title":"主键策略","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","附录","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/附录/未分类/一发入魂/主键策略.md","filePath":"posts/java快速入门/附录/未分类/一发入魂/主键策略.md"}'),a={name:"posts/java快速入门/附录/未分类/一发入魂/主键策略.md"};function r(s,e,i,l,p,n){return d(),c("div",null,[...e[0]||(e[0]=[t('<div><p>在定义实体类时，用<code>@TableId</code>指定主键，而其<code>type</code>属性，可以指定主键策略。 <code>mp</code>支持多种主键策略，默认的策略是基于雪花算法的自增<code>id</code>。全部主键策略定义在了枚举类<code>IdType</code>中，<code>IdType</code>有如下的取值 • <code>AUTO</code> 数据库<code>ID</code>自增，依赖于数据库。在插入操作生成<code>SQL</code>语句时，不会插入主键这一列 • <code>NONE</code> 未设置主键类型。若在代码中没有手动设置主键，则会根据主键的全局策略自动生成（默认的主键全局策略是基于雪花算法的自增<code>ID</code>） • <code>INPUT</code> 需要手动设置主键，若不设置。插入操作生成<code>SQL</code>语句时，主键这一列的值会是<code>null</code>。<code>oracle</code>的序列主键需要使用这种方式 • <code>ASSIGN_ID</code> 当没有手动设置主键，即实体类中的主键属性为空时，才会自动填充，使用雪花算法 • <code>ASSIGN_UUID</code> 当实体类的主键属性为空时，才会自动填充，使用<code>UUID</code> • <code>....</code>（还有几种是已过时的，就不再列举） 可以针对每个实体类，使用<code>@TableId</code>注解指定该实体类的主键策略，这可以理解为局部策略。若希望对所有的实体类，都采用同一种主键策略，挨个在每个实体类上进行配置，则太麻烦了，此时可以用主键的全局策略。只需要在<code>application.yml</code>进行配置即可。比如，配置了全局采用自增主键策略 <code># application.ymlmybatis-plus:global-config:db-config:id-type:auto</code>复制代码 下面对不同主键策略的行为进行演示 • <code>AUTO</code> 在<code>User</code>上对<code>id</code>属性加上注解，然后将<code>MYSQL</code>的<code>user</code>表修改其主键为自增。</p><p>@EqualsAndHashCode(callSuper = false)@DatapublicclassUserextendsModel&lt;User&gt; { @TableId(type = IdType.AUTO)privateLong id; @TableField(condition = SqlCondition.LIKE)privateString name; @TableField(condition = &quot;%s &gt; #{%s}&quot;)privateInteger age; privateString email; privateLong managerId; privateLocalDateTime createTime; } 复制代码 测试</p><p>@TestpublicvoidtestAuto(){ Useruser=newUser(); user.setName(&quot; 我是青蛙呱呱</p><p>&quot;); user.setAge(99); user.setEmail(&quot;<a href="mailto:frog@baomidou.com" target="_blank" rel="noreferrer">frog@baomidou.com</a>&quot;); user.setCreateTime(LocalDateTime.now()); userMapper.insert(user); System.out.println(user.getId()); } 复制代码 结果</p><p>可以看到，代码中没有设置主键<code>ID</code>，发出的<code>SQL</code>语句中也没有设置主键<code>ID</code>，并且插入结束后，主键<code>ID</code>会被写回到实体对象。 • <code>NONE</code> 在<code>MYSQL</code>的<code>user</code>表中，去掉主键自增。然后修改<code>User</code>类（若不配置<code>@TableId</code>注解，默认主键策略也是<code>NONE</code>） <code>@TableId(type = IdType.NONE)privateLong id;</code> 复制代码 插入时，若实体类的主键<code>ID</code>有值，则使用之；若主键<code>ID</code>为空，则使用主键全局策略，来生成一个<code>ID</code>。 • 其余的策略类似，不赘述 小结 <code>AUTO</code>依赖于数据库的自增主键，插入时，实体对象无需设置主键，插入成功后，主键会被写回实体对象。 <code>INPUT</code>完全依赖于用户输入。实体对象中主键<code>ID</code>是什么，插入到数据库时就设置什么。若有值便设置值，若为<code>null</code>则设置<code>null</code> 其余的几个策略，都是在实体对象中主键<code>ID</code>为空时，才会自动生成。 <code>NONE</code>会跟随全局策略，<code>ASSIGN_ID</code>采用雪花算法，<code>ASSIGN_UUID</code>采用<code>UUID</code> 全局配置，在<code>application.yml</code>中进行即可；针对单个实体类的局部配置，使用<code>@TableId</code>即可。对于某个实体类，若它有局部主键策略，则采用之，否则，跟随全局策略。</p></div>',1)])])}const T=o(a,[["render",r]]);export{u as __pageData,T as default};
